mapper.select:
SELECT
    (SELECT COUNT(*) FROM patients    WHERE deleted = false)  AS total_patients,
    (SELECT COUNT(*) FROM doctors     WHERE deleted = false)  AS total_doctors,
    COUNT(DISTINCT a.id)                                       AS total_appointments,
    COUNT(DISTINCT a.id) FILTER (WHERE a.status = 'COMPLETED')  AS completed_appointments,
    COUNT(DISTINCT a.id) FILTER (WHERE a.status = 'CANCELLED')  AS cancelled_appointments,
    COUNT(DISTINCT asmt.id)                                    AS total_assessments,
    COUNT(DISTINCT asmt.id) FILTER (WHERE asmt.status = 'COMPLETED') AS completed_assessments,
    COUNT(DISTINCT tp.id)                                      AS total_therapy_plans,
    COUNT(DISTINCT tp.id) FILTER (WHERE tp.status = 'ACTIVE') AS active_therapy_plans,
    COUNT(DISTINCT ts.id)                                      AS total_sessions,
    COUNT(DISTINCT ts.id) FILTER (WHERE ts.status = 'COMPLETED') AS completed_sessions
FROM
    (SELECT 1) AS dummy
LEFT JOIN appointments     a    ON a.deleted    = false
    AND CAST(a.appointment_date AS DATE) >= #{from}
    AND CAST(a.appointment_date AS DATE) <= #{to}
LEFT JOIN assessments      asmt ON asmt.deleted = false
    AND CAST(asmt.assessment_date AS DATE) >= #{from}
    AND CAST(asmt.assessment_date AS DATE) <= #{to}
LEFT JOIN therapy_plans    tp   ON tp.deleted   = false
    AND tp.start_date >= #{from}
    AND tp.start_date <= #{to}
LEFT JOIN therapy_sessions ts   ON ts.deleted   = false
    AND CAST(ts.session_date AS DATE) >= #{from}
    AND CAST(ts.session_date AS DATE) <= #{to}
